}

/**
 * The result of applying a single {@link Transform}.
 */
export type TransformOutput = {
  /** Absolute or project-relative paths of the source files that were changed. */
  filesChanged: string[]
  /** Optional human-readable notes about what the transform did. */
  notes?: string[]
}

