 * Describes a single code transform that can be applied to a ts-morph `Project`.
 */
export type Transform = {
  /**
   * Applies the transform to the supplied {@link TransformContext}.
   *
   * May be synchronous or asynchronous.
   */
  apply: (ctx: TransformContext) => Promise<TransformOutput> | TransformOutput
  /** Human-readable description of what the transform does. */
  description: string
  /** Unique, stable identifier for the transform. */
  name: string
}
