[metadata] {"type": "create", "filePath": "/workspace/repo/packages/codemod/src/runner.ts", "content": "import type { Project } from 'ts-morph'

import type { Transform } from './types.js'

/**
 * The result of running a single {@link Transform} via {@link runTransforms}.
 */
export type TransformRunResult = {
  /** Error thrown by the transform, if any. */
  error?: Error
  /** Paths of the source files the transform changed (empty if it threw). */
  filesChanged: string[]
  /** The transform's name. */
  name: string
  /** Optional human-readable notes returned by the transform. */
  notes?: string[]
}

/**
 * The aggregate result of running a set of transforms.
 */
export type RunTransformsResult = {
  /** `true` if any transform threw an error. */
  failed: boolean
  /** One entry per transform, in the order the transforms were supplied. */
  results: TransformRunResult[]
}

/**
 * Runs all supplied transforms in order against a ts-morph `Project`.
 *
 * Every transform is executed regardless of whether an earlier transform threw
 * an error — failures are collected per transform rather than aborting the run.
 *
 * @returns An object whose `failed` flag is `true` if any transform threw, and
 * whose `results` array contains one entry per transform.
 */
export async function runTransforms({
  project,
  transforms,
}: {
  project: Project
  transforms: Transform[]
}): Promise<RunTransformsResult> {
  const results: TransformRunResult[] = []
  let failed = false

  for (const transform of transforms) {
    try {
      const output = await transform.apply({ project })
      const result: TransformRunResult = {
        name: transform.name,
        filesChanged: output.filesChanged,
      }
      if (output.notes) {
        result.notes = output.notes
      }
      results.push(result)
    } catch (err) {
      failed = true
      const error = err instanceof Error ? err : new Error(String(err))
      results.push({
        name: transform.name,
        error,
        filesChanged: [],
      })
    }
  }

  return { failed, results }
}
