import type { Transform } from '../types.js'

/**
 * Test helper that applies a {@link Transform} to an in-memory source string.
 *
 * Creates an in-memory ts-morph `Project` containing `source` as a single
 * TypeScript file (default filename `input.ts`), applies the transform by
 * calling `transform.apply({ project })`, and returns the resulting file's
 * source text.
 */
export async function runTransform({
  filename = 'input.ts',
  source,
  transform,
}: {
  filename?: string
  source: string
  transform: Transform
}): Promise<string> {
  const project = new Project({ useInMemoryFileSystem: true })
  const sourceFile = project.createSourceFile(filename, source, { overwrite: true })

  await transform.apply({ project })

  return sourceFile.getFullText()
}
