import { exampleNoop } from './src/transforms/example-noop/index.js'
import { runTransform } from './src/utils/test-helpers.js'

describe('parseFlags', () => {
  it('defaults', () => {
    expect(parseFlags([])).toEqual({
      dry: false,
      list: false,
      path: process.cwd(),
      print: false,
      transform: undefined,
    })
  })
  it('positional path', () => {
    expect(parseFlags(['./src']).path).toBe('./src')
  })
  it('flags + transform + dry-run alias', () => {
    const f = parseFlags(['./x', '--dry-run', '--list', '--print', '--transform', 'rename-slate-export'])
    expect(f).toEqual({
      dry: true,
      list: true,
      path: './x',
      print: true,
      transform: 'rename-slate-export',
    })
  })
})

describe('runTransforms', () => {
  it('continues past failures and reports failed', async () => {
    const boom = { name: 'boom', description: 'x', apply: () => { throw new Error('nope') } }
    const ok = { name: 'ok', description: 'y', apply: () => ({ filesChanged: ['a.ts'], notes: ['n'] }) }
    const { Project } = await import('ts-morph')
    const res = await runTransforms({ project: new Project({ useInMemoryFileSystem: true }), transforms: [boom, ok] })
    expect(res.failed).toBe(true)
    expect(res.results.length).toBe(2)
    expect(res.results[0].error).toBeInstanceOf(Error)
    expect(res.results[0].filesChanged).toEqual([])
    expect(res.results[1]).toEqual({ name: 'ok', filesChanged: ['a.ts'], notes: ['n'] })
  })
  it('failed=false when all succeed', async () => {
    const { Project } = await import('ts-morph')
    const res = await runTransforms({ project: new Project({ useInMemoryFileSystem: true }), transforms: [exampleNoop] })
    expect(res.failed).toBe(false)
  })
})

describe('exampleNoop', () => {
